WITH RECURSIVE seg(n, run, top, want) AS (SELECT 0, l.run, l.depth, $2::bigint FROM {s}.commit_lineage l WHERE l.commit_id = $1 UNION ALL SELECT seg.n + 1, p.run, p.depth, seg.want - (seg.top - b.depth + 1) FROM seg CROSS JOIN LATERAL (SELECT f.commit_id, f.depth FROM {s}.commit_lineage f WHERE f.run = seg.run AND f.depth <= seg.top ORDER BY f.depth LIMIT 1) b JOIN {s}."commit" o ON o.commit_id = b.commit_id JOIN {s}.commit_lineage p ON p.commit_id = o.parent_commit_id WHERE seg.want > seg.top - b.depth + 1) SELECT c.commit_id, c.layer_stack_id, c.root_id, c.parent_commit_id, c.base_layer_id, c.second_parent_id, c.branch_id, c.via, c.message, c.merged_from_id, c.created_ms, c.logical, c.new_canonical, c.new_stored, c.new_metadata, c.lww, c.displaced_id, c.attempt, c.history_serial, seg.n::bigint, l.depth FROM seg JOIN {s}.commit_lineage l ON l.run = seg.run AND l.depth <= seg.top AND l.depth > seg.top - seg.want JOIN {s}."commit" c ON c.commit_id = l.commit_id ORDER BY seg.n, l.depth DESC LIMIT $2;
